  <script>
    // ---- Config ----
    var SHEET_ID = "1rivD5luGlZqq6MCEUVvlT263OfUKXrzH6cr9cf0nG3A";
    var SHEET_NAME = "Job Applications Log";
    var JULIE_ENDPOINT = "https://hsndm566.app.n8n.cloud/webhook/julie-chat";
    var REFRESH_MS = 60000;
    var chart;

    function gvizUrl() {
      return "https://docs.google.com/spreadsheets/d/" + SHEET_ID +
        "/gviz/tq?sheet=" + encodeURIComponent(SHEET_NAME) + "&tqx=out:json";
    }
    function parseGviz(text) {
      var start = text.indexOf("{");
      var end = text.lastIndexOf("}");
      var obj = JSON.parse(text.substring(start, end + 1));
      var cols = obj.table.cols.map(function (c) { return (c.label || c.id || "").toString().trim(); });
      return obj.table.rows.map(function (r) {
        var o = {};
        (r.c || []).forEach(function (cell, i) { o[cols[i] || ("col" + i)] = cell ? cell.v : null; });
        return o;
      });
    }
    function pick(row, names) {
      var keys = Object.keys(row);
      for (var n = 0; n < names.length; n++) {
        for (var k = 0; k < keys.length; k++) {
          if (keys[k].toLowerCase().indexOf(names[n]) !== -1) return row[keys[k]];
        }
      }
      return "";
    }
    function classify(status) {
      var s = (status || "").toString().toLowerCase();
      if (s.indexOf("offer") !== -1) return "offer";
      if (s.indexOf("interview") !== -1) return "interview";
      if (s.indexOf("reject") !== -1) return "rejected";
      return "applied";
    }

    async function loadData() {
      document.getElementById("errorMsg").classList.add("hidden");
      try {
        var res = await fetch(gvizUrl());
        var text = await res.text();
        var rows = parseGviz(text);
        render(rows);
        document.getElementById("lastUpdated").textContent = "Updated " + new Date().toLocaleTimeString();
      } catch (e) {
        var em = document.getElementById("errorMsg");
        em.textContent = "Could not load the sheet. Make sure it is shared as 'Anyone with the link can view'. (" + e.message + ")";
        em.classList.remove("hidden");
      }
    }

    function render(rows) {
      var counts = { applied: 0, interview: 0, offer: 0, rejected: 0 };
      rows.forEach(function (r) { counts[classify(pick(r, ["status"]))]++; });

      setStat("statTotal", rows.length);
      setStat("statApplied", counts.applied);
      setStat("statInterview", counts.interview);
      setStat("statOffer", counts.offer);

      // Chart
      document.getElementById("chartSkeleton").classList.add("hidden");
      var canvas = document.getElementById("statusChart");
      canvas.classList.remove("hidden");
      var data = {
        labels: ["Applied", "Interview", "Offer", "Rejected"],
        datasets: [{ data: [counts.applied, counts.interview, counts.offer, counts.rejected],
          backgroundColor: ["#3b82f6", "#f59e0b", "#22c55e", "#ef4444"] }]
      };
      if (chart) { chart.data = data; chart.update(); }
      else { chart = new Chart(canvas, { type: "doughnut", data: data, options: { plugins: { legend: { position: "bottom" } } } }); }

      // Recent activity (last 8)
      var body = document.getElementById("activityBody");
      body.innerHTML = "";
      var recent = rows.slice(-8).reverse();
      if (!recent.length) { body.innerHTML = '<tr><td colspan="4" class="py-3 text-slate-400">No records yet.</td></tr>'; return; }
      recent.forEach(function (r) {
        var tr = document.createElement("tr");
        tr.className = "border-b last:border-0 fade-in";
        tr.innerHTML = "<td class='py-2 pr-3'>" + fmt(pick(r, ["date", "applied"])) + "</td>" +
          "<td class='py-2 pr-3'>" + fmt(pick(r, ["company", "employer"])) + "</td>" +
          "<td class='py-2 pr-3'>" + fmt(pick(r, ["role", "position", "title"])) + "</td>" +
          "<td class='py-2'>" + badge(pick(r, ["status"])) + "</td>";
        body.appendChild(tr);
      });
    }
    function fmt(v) { return v == null || v === "" ? "—" : String(v); }
    function setStat(id, v) { var el = document.getElementById(id); el.textContent = v; el.classList.add("fade-in"); }
    function badge(status) {
      var c = classify(status);
      var map = { applied: "bg-blue-100 text-blue-700", interview: "bg-amber-100 text-amber-700", offer: "bg-green-100 text-green-700", rejected: "bg-red-100 text-red-700" };
      return "<span class='px-2 py-0.5 rounded-full text-xs " + map[c] + "'>" + fmt(status) + "</span>";
    }

    document.getElementById("refreshBtn").addEventListener("click", loadData);
    loadData();
    setInterval(loadData, REFRESH_MS);

    // ---- Julie chatbot ----
    var panel = document.getElementById("juliePanel");
    document.getElementById("julieToggle").addEventListener("click", function () { panel.classList.toggle("hidden"); });
    function julieMsg(text, who) {
      var log = document.getElementById("julieLog");
      var d = document.createElement("div");
      d.className = who === "user" ? "text-right" : "text-left";
      d.innerHTML = "<span class='inline-block px-3 py-2 rounded-lg " + (who === "user" ? "bg-indigo-600 text-white" : "bg-slate-100") + "'>" + text + "</span>";
      log.appendChild(d); log.scrollTop = log.scrollHeight;
    }
    document.getElementById("julieForm").addEventListener("submit", async function (e) {
      e.preventDefault();
      var input = document.getElementById("julieInput");
      var q = input.value.trim(); if (!q) return;
      julieMsg(q, "user"); input.value = "";
      try {
        var res = await fetch(JULIE_ENDPOINT, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ message: q }) });
        var data = await res.json().catch(function () { return {}; });
        julieMsg(data.reply || data.output || "Sorry, I couldn't reach the assistant right now.", "bot");
      } catch (err) { julieMsg("Network error contacting Julie.", "bot"); }
    });
  </script>
</body>
</html>
