const pages = $("Build Pages").all();
const verify = $("Verify Live").all();
const design = $("Design Review").all();
const content = $("Content Review").all();
const out = [];
for (let i = 0; i < pages.length; i++) {
  const v = verify[i] ? verify[i].json : {};
  const status = (v.statusCode !== undefined) ? v.statusCode : (v.error ? "error" : "unknown");
  const d = design[i] ? design[i].json : null;
  const c = content[i] ? content[i].json : null;
  out.push({ json: {
    filename: pages[i].json.filename,
    url: "https://hsndm.tech/" + pages[i].json.filename,
    live_http_status: status,
    is_live: status === 200,
    design_ux_review: d ? (d.text || d.output || "(empty)") : "(no review)",
    design_model: d ? (d.model_used || d.model || "unknown") : "none",
    content_seo_review: c ? (c.text || c.output || "(empty)") : "(no review)",
    content_model: c ? (c.model_used || c.model || "unknown") : "none",
  }});
}
return out;
